-- =====================================================================
-- LocalAlert base tables (the original amber_alert_db schema).
-- Only needed for a NEW, empty database: run this first, then 001 to 010 in order.
-- An existing amber_alert_db already has these tables, so skip this file.
-- =====================================================================
CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE roles (role_id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, role_name varchar(50) NOT NULL UNIQUE, description text, created_at timestamp DEFAULT CURRENT_TIMESTAMP, updated_at timestamp DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users (user_id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, role_id uuid NOT NULL, first_name varchar(50) NOT NULL, last_name varchar(50) NOT NULL, email varchar(100) NOT NULL UNIQUE, password_hash text NOT NULL, phone_number varchar(10), is_verified boolean DEFAULT false, created_at timestamp DEFAULT CURRENT_TIMESTAMP, updated_at timestamp DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_role FOREIGN KEY (role_id) REFERENCES roles(role_id) ON DELETE CASCADE);
CREATE TABLE alerts (alert_id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, created_by uuid NOT NULL, child_name varchar(100) NOT NULL, age integer, gender varchar(10), description text, photo_url text, latitude numeric(10,8), longitude numeric(11,8), last_seen_time timestamp, clothing_description text, status varchar(20) DEFAULT 'active', created_at timestamp DEFAULT CURRENT_TIMESTAMP, updated_at timestamp DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_alert_creator FOREIGN KEY (created_by) REFERENCES users(user_id) ON DELETE CASCADE);
CREATE INDEX idx_alert_location ON alerts (latitude, longitude); CREATE INDEX idx_alert_status ON alerts (status);
CREATE TABLE notifications (notification_id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, user_id uuid NOT NULL, alert_id uuid NOT NULL, title varchar(100) NOT NULL, message text NOT NULL, is_read boolean DEFAULT false, created_at timestamp DEFAULT CURRENT_TIMESTAMP, updated_at timestamp DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_notification_alert FOREIGN KEY (alert_id) REFERENCES alerts(alert_id) ON DELETE CASCADE, CONSTRAINT fk_notification_user FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE);
CREATE INDEX idx_reports_user ON notifications (user_id); CREATE INDEX idx_reports_user6 ON notifications (user_id);
CREATE TABLE sighting_reports (report_id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, alert_id uuid NOT NULL, user_id uuid NOT NULL, description text, photo_url text, latitude numeric(10,8), longitude numeric(11,8), status varchar(20) DEFAULT 'PENDING', reported_at timestamp DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_report_alert FOREIGN KEY (alert_id) REFERENCES alerts(alert_id) ON DELETE CASCADE, CONSTRAINT fk_report_user FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE);
CREATE INDEX idx_reports_alert ON sighting_reports (alert_id);
CREATE TABLE alert_history (history_id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, alert_id uuid NOT NULL, changed_by uuid NOT NULL, old_status varchar(20), new_status varchar(20), change_description text, updated_at timestamp DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_alert_history FOREIGN KEY (alert_id) REFERENCES alerts(alert_id) ON DELETE CASCADE, CONSTRAINT fk_alert_history_user FOREIGN KEY (changed_by) REFERENCES users(user_id) ON DELETE CASCADE);
